{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Therapeutic support in {{CITY}}, {{STATE}} — confidential, trauma-informed care for anxiety, relationships, life transitions, and burnout." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="lux-gallery">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="about.html">About</a>
        <a href="specialties.html">Specialties</a>
        <a href="approach.html">Approach</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html" class="cta">Book</a>
        <button id="menuToggle" aria-label="Open menu">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO (gallery-style with large SVG) -->
    <section class="hero" id="hero">
      <div class="hero-grid wrap">
        <div class="hero-copy">
          <h1 class="eyebrow">Welcome — I'm {{THERAPIST_NAME}}</h1>
          <h2 class="title">Compassionate, confidential therapy to steady you through change</h2>
          <p class="lead">I offer trauma-informed psychotherapy and practical tools to reduce anxiety, repair relationships, and restore balance. Sessions are individual, secure, and tailored to your needs.</p>
          <div class="hero-actions">
            <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button class="outline" id="downloadGuide">Get my welcome guide</button>
          </div>
          <p class="meta">In-person in {{CITY}}, {{STATE}} and telehealth available. License: {{LICENSE}}</p>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Abstract therapeutic scene" />
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof wrap" aria-label="Client stories">
      <h3 class="section-title">Client reflections</h3>
      <div class="testimonials">
        <blockquote>
          "Working here felt safe and clear — practical tools that actually fit my life." 
          <cite>— L., {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "I appreciated the steady presence and focus on small, doable change." 
          <cite>— R., {{STATE}}</cite>
        </blockquote>
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="Therapist portrait illustration" />
          <p class="byline">{{THERAPIST_NAME}}, {{LICENSE}}</p>
        </div>
      </div>
    </section>

    <!-- BENEFITS (cards gallery) -->
    <section class="benefits wrap" id="benefits">
      <h3 class="section-title">Ways I support people</h3>
      <div class="cards">
        <article class="card">
          <h4>Reduce anxiety</h4>
          <p>Evidence-informed strategies to interrupt worry cycles and increase calm in day-to-day life.</p>
        </article>
        <article class="card">
          <h4>Process trauma gently</h4>
          <p>Trauma-aware care that prioritizes safety, pacing, and resources to regulate the nervous system.</p>
        </article>
        <article class="card">
          <h4>Repair relationships</h4>
          <p>Communication skills and patterns work to restore connection and mutual understanding.</p>
        </article>
        <article class="card">
          <h4>Life transitions & burnout</h4>
          <p>Guided planning and boundary work to help you move through change with clarity and rest.</p>
        </article>
      </div>
    </section>

    <!-- PROCESS (step gallery) -->
    <section class="process wrap" id="process">
      <h3 class="section-title">How we might work together</h3>
      <ol class="steps">
        <li>
          <strong>1. Connect</strong>
          <p>We’ll start with a 20-minute consult call to clarify needs and fit. You can ask questions about modality, scheduling, and confidentiality.</p>
        </li>
        <li>
          <strong>2. Begin</strong>
          <p>Initial sessions focus on safety, consent, and establishing goals. I blend evidence-based techniques with relational support.</p>
        </li>
        <li>
          <strong>3. Integrate</strong>
          <p>We track progress, learn tools you can use between sessions, and adjust pacing so it feels manageable and respectful.</p>
        </li>
        <li>
          <strong>4. Transition</strong>
          <p>When work concludes we plan a gradual step-down and offer resources for ongoing growth.</p>
        </li>
      </ol>
      <p class="process-note">Confidentiality is foundational. For details about limits (e.g., imminent harm, mandated reporting) I provide clear written information at intake.</p>
    </section>

    <!-- FAQ (compact gallery) -->
    <section class="faq wrap" id="faq">
      <h3 class="section-title">Common questions</h3>
      <dl>
        <dt>What modalities do you use?</dt>
        <dd>I draw on CBT, attachment-informed work, trauma-focused strategies, and mindfulness—tailored to your goals. ({{MODALITIES}})</dd>

        <dt>How long is a session?</dt>
        <dd>Standard sessions are 50 minutes. Longer or intensive sessions are available by arrangement.</dd>

        <dt>Is telehealth secure?</dt>
        <dd>I use a HIPAA-aligned platform for telehealth. We’ll review privacy and consent before starting.</dd>
      </dl>
      <p class="disclaimer">If you are in crisis or at immediate risk of harming yourself or others, call emergency services or your local crisis line. Online therapy is not an emergency service.</p>
    </section>

    <!-- LEAD MAGNET (modal signup) -->
    <section class="lead-magnet wrap" id="lead-magnet">
      <h3 class="section-title">A short guide to starting therapy</h3>
      <p>Sign up to receive a concise welcome guide that explains what to expect, how to prepare, and ways to make the most of early sessions.</p>
      <form id="leadForm" class="inline-form" onsubmit="return false;">
        <label for="email">Email</label>
        <input id="email" name="email" type="email" placeholder="name@example.com" required />
        <button id="submitLead" class="primary">Send me the guide</button>
      </form>
      <p class="privacy-note">I keep your contact details private and never sell them. By signing up you consent to receiving occasional emails about appointments and resources.</p>
    </section>

    <!-- CALL TO ACTION (gallery footer) -->
    <section class="final-cta wrap">
      <div class="cta-grid">
        <div>
          <h3>Ready to get started?</h3>
          <p>Schedule a consult to see if we’re a good fit — I prioritize clarity and safety in every step.</p>
        </div>
        <div class="cta-actions">
          <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="outline" href="contact.html">Ask a question</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer wrap">
    <div class="footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Licensed: {{LICENSE}}</p>
      </div>
      <div>
        <p>Confidentiality & privacy: sessions and notes are kept confidential except where required by law. Therapy is supportive care and not a substitute for emergency services.</p>
      </div>
      <div class="footer-links">
        <a href="privacy.html">Privacy</a>
        <a href="fees.html">Fees & insurance</a>
        <a href="book.html">Book</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
