{"path":"assets/css/styles.css","content":"/* Lux Gallery — premium palette, spacious grid */
:root{
  --bg:#fbfaf9; --muted:#6b6b6b; --accent:#8b6eff; --accent-2:#ff9aa2; --ink:#111111; --card:#ffffff; --radius:12px;
  --max-width:1100px;
  font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);line-height:1.5}
.wrap{max-width:var(--max-width);margin:0 auto;padding:36px}
.site-header{background:linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6));backdrop-filter:blur(6px);position:sticky;top:0;z-index:10}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--ink);text-decoration:none;font-size:18px}
.main-nav a{margin-left:18px;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-copy .eyebrow{color:var(--accent-2);font-weight:600;margin:0 0 8px}
.title{font-size:28px;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions .primary{background:var(--accent);color:#fff;padding:12px 18px;border-radius:10px;text-decoration:none;margin-right:10px}
.hero-actions .outline{background:transparent;border:1px solid var(--accent);padding:10px 16px;border-radius:10px}
.hero-art img{width:100%;height:auto;border-radius:14px;box-shadow:0 10px 30px rgba(17,17,17,0.06)}
.social-proof{padding:34px 0}
.social-proof .section-title{margin:0 0 18px}
.testimonials{display:grid;grid-template-columns:1fr 1fr 220px;gap:18px;align-items:center}
.testimonials blockquote{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(11,10,14,0.04);margin:0}
.testimonials cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.avatar img{width:100%;border-radius:12px}
.benefits .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:16px}
.card{background:linear-gradient(180deg,#fff,#fcfbff);padding:20px;border-radius:12px;box-shadow:0 6px 20px rgba(13,12,22,0.03)}
.process .steps{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;list-style:none;padding:0;margin:16px 0}
.process .steps li{background:var(--card);padding:16px;border-radius:12px}
.process-note{color:var(--muted);font-size:13px;margin-top:12px}
.faq dl{display:grid;gap:12px}
.faq dt{font-weight:600}
.faq dd{margin:0;color:var(--muted)}
.lead-magnet .inline-form{display:flex;gap:8px;align-items:center;margin-top:12px}
.inline-form input{padding:10px;border-radius:10px;border:1px solid #e6e6e9;flex:1}
.inline-form button.primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:none}
.final-cta{background:linear-gradient(90deg,rgba(139,110,255,0.08),rgba(255,154,158,0.04));padding:28px;border-radius:12px;margin-top:20px}
.cta-grid{display:flex;justify-content:space-between;align-items:center}
.cta-actions a{display:inline-block;margin-left:12px}
.site-footer{padding:36px 0;color:var(--muted);font-size:14px}
.footer-grid{display:grid;grid-template-columns:1fr 2fr 1fr;gap:16px}
.privacy-note,.disclaimer{font-size:13px;color:var(--muted)}
/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .testimonials{grid-template-columns:1fr;}
  .benefits .cards{grid-template-columns:repeat(2,1fr)}
  .process .steps{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple interactions: lead magnet submit and menu toggle
  var menuToggle=document.getElementById('menuToggle');
  if(menuToggle){
    menuToggle.addEventListener('click',function(){
      document.body.classList.toggle('nav-open');
      alert('Navigation toggled for demo.');
    });
  }

  var downloadBtn=document.getElementById('downloadGuide');
  if(downloadBtn){
    downloadBtn.addEventListener('click',function(){
      var ok=confirm('Would you like the welcome guide emailed to you?');
      if(ok){
        window.location.hash='#lead-magnet';
        document.getElementById('email') && document.getElementById('email').focus();
      }
    });
  }

  var leadForm=document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email=document.getElementById('email').value;
      if(!email || !email.includes('@')){
        alert('Please provide a valid email address.');
        return;
      }
      // Simulated submission
      alert('Thanks — the guide will be sent to ' + email + '. You can also reach us at {{EMAIL}}');
      leadForm.reset();
    });
    // Also wire the button in case form uses onsubmit=false
    var submitBtn=document.getElementById('submitLead');
    submitBtn && submitBtn.addEventListener('click',function(){ leadForm.dispatchEvent(new Event('submit')) });
  }
})();
"} 
